module max_avg_subarray(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] arr_0,\n    input [7:0] arr_1,\n    input [7:0] arr_2,\n    input [7:0] arr_3,\n    input [7:0] arr_4,\n    input [7:0] arr_5,\n    input [7:0] arr_6,\n    input [7:0] arr_7,\n    input [2:0] K,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] IDLE           = 4'd0;\n    localparam [3:0] START          = 4'd1;\n    localparam [3:0] INIT_I         = 4'd2;\n    localparam [3:0] ACCUM          = 4'd3;\n    localparam [3:0] COMPARE        = 4'd4;\n    localparam [3:0] COMPUTE_RESULT = 4'd5;\n    localparam [3:0] DONE_STATE     = 4'd6;\n\n    // Internal registers\n    reg [3:0] state, next_state;\n    reg [7:0] loaded_arr [0:7];\n    reg [15:0] best_sum;\n    reg [3:0] best_len;\n    reg [15:0] current_sum;\n    reg [3:0] i;\n    reg [3:0] j;\n    reg [4:0] cycle_count;\n    reg [3:0] current_len;\n    reg [3:0] K_reg;\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            best_sum <= 16'd0;\n            best_len <= 4'd0;\n            current_sum <= 16'd0;\n            i <= 4'd0;\n            j <= 4'd0;\n            cycle_count <= 5'd0;\n            current_len <= 4'd0;\n            done <= 1'b0;\n            result <= 32'd0;\n            K_reg <= 3'd0;\n            // Initialize array\n            loaded_arr[0] <= 8'd0;\n            loaded_arr[1] <= 8'd0;\n            loaded_arr[2] <= 8'd0;\n            loaded_arr[3] <= 8'd0;\n            loaded_arr[4] <= 8'd0;\n            loaded_arr[5] <= 8'd0;\n            loaded_arr[6] <= 8'd0;\n            loaded_arr[7] <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 5'd0;\n                    if (start) begin\n                        // Latch inputs\n                        loaded_arr[0] <= arr_0;\n                        loaded_arr[1] <= arr_1;\n                        loaded_arr[2] <= arr_2;\n                        loaded_arr[3] <= arr_3;\n                        loaded_arr[4] <= arr_4;\n                        loaded_arr[5] <= arr_5;\n                        loaded_arr[6] <= arr_6;\n                        loaded_arr[7] <= arr_7;\n                        K_reg <= K;\n                        best_sum <= 16'd0;\n                        best_len <= 4'd0;\n                        state <= INIT_I;\n                    end\n                end\n\n                INIT_I: begin\n                    j <= i;\n                    current_sum <= 16'd0;\n                    current_len <= 4'd0;\n                    if ((i + K_reg) > 4'd8) begin\n                        state <= COMPUTE_RESULT;\n                    end else begin\n                        state <= ACCUM;\n                    end\n                end\n\n                ACCUM: begin\n                    current_sum <= current_sum + loaded_arr[j];\n                    current_len <= current_len + 4'd1;\n                    j <= j + 4'd1;\n                    if (current_len == (K_reg - 4'd1)) begin\n                        state <= COMPARE;\n                    end\n                end\n\n                COMPARE: begin\n                    // Compare using cross-multiplication\n                    if (current_sum * best_len > best_sum * current_len) begin\n                        best_sum <= current_sum;\n                        best_len <= current_len;\n                    end else if (current_sum * best_len == best_sum * current_len) begin\n                        if (current_len > best_len) begin\n                            best_sum <= current_sum;\n                            best_len <= current_len;\n                        end\n                    end\n\n                    // Extend subarray if possible\n                    if (j < 4'd8) begin\n                        current_sum <= current_sum + loaded_arr[j];\n                        current_len <= current_len + 4'd1;\n                        j <= j + 4'd1;\n                    end else begin\n                        i <= i + 4'd1;\n                        state <= INIT_I;\n                    end\n                end\n\n                COMPUTE_RESULT: begin\n                    if (best_len != 4'd0) begin\n                        result <= ({best_sum, 16'd0}) / best_len;\n                    end else begin\n                        result <= 32'd0;\n                    end\n                    state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n\n            cycle_count <= cycle_count + 5'd1;\n            // Timeout protection\n            if (cycle_count >= 5'd25) begin\n                state <= DONE_STATE;\n            end\n        end\n    end\nendmodule